import * as E from '../../src/empire/state.js';
import {ALL_GUIDES}from'../../src/empire/minigame-guides.js';
import {TutorialUI,tutorialSettings}from'../../src/empire/tutorial-ui.js';
const state=E.newState();state.money=123456789n;state.inventory[1]=3;
const originalEconomy=E.encode({money:state.money,copper:state.copper,xp:state.xp,inventory:state.inventory,stats:state.stats});
let saves=0,starts=0,report={};const output=document.querySelector('#qa-report');
const display=()=>{const economy=E.encode({money:state.money,copper:state.copper,xp:state.xp,inventory:state.inventory,stats:state.stats});output.textContent=JSON.stringify({...report,economyUnchanged:economy===originalEconomy,completed:state.tutorials.completed,localSaves:saves,realChallengeStarts:starts},null,2);};
const ui=new TutorialUI({state:()=>state,save:()=>{saves++;display();},notify:text=>{report.notice=text;display();}});
const select=document.querySelector('#qa-guide');select.innerHTML=Object.values(ALL_GUIDES).map(g=>`<option value="${g.id}">${g.id} · ${g.name}</option>`).join('');
document.querySelector('#qa-first').onclick=()=>{if(!ui.first(select.value,()=>{starts++;display();})){report.notice='Already seen; no tutorial shown.';display();}};
document.querySelector('#qa-replay').onclick=()=>ui.open(select.value,{replay:true});document.querySelector('#qa-library').onclick=()=>ui.library();document.querySelector('#qa-settings').innerHTML=tutorialSettings(state);
document.querySelector('#qa-coverage').onclick=async()=>{const checks=[];for(const g of Object.values(ALL_GUIDES)){ui.open(g.id,{replay:true});for(let i=0;i<g.tutorialSteps.length;i++){ui.step=i;ui.show();const step=g.tutorialSteps[i],target=ui.root.querySelector(step.target);checks.push({id:g.id,step:i,target:step.target,resolved:!!target,enabled:target?.disabled!==true});}ui.dismiss();await new Promise(requestAnimationFrame);}report={guideCount:Object.keys(ALL_GUIDES).length,steps:checks.length,failures:checks.filter(c=>!c.resolved||!c.enabled),complete:checks.every(c=>c.resolved&&c.enabled)};display();};
const nextFrame=()=>new Promise(requestAnimationFrame);
async function interactions(){const rows=[];for(const [family,id,actions]of[['timing',1,['hit']],['sliders',4,['slider']],['memory',5,['pulse']],['rotations',8,['tile']],['dragging and placement',2,['select','rotate','slot']],['scheduling',68,['select','place']],['logic',47,['input','cross']],['rhythm',16,['beat']],['routing',29,['edge']],['composites',2030,['slider','press']],['gold',1001,['nudge','shake']]]){const before=E.encode(state);ui.open(id,{replay:true});ui.demo.response();ui.paint();const original=E.encode(ui.demo.game);for(const action of actions){const target=ui.root.querySelector(`[data-g="${action}"]`);if(!target)throw Error(family+' missing '+action);if(target.tagName==='INPUT'){target.value=String(Number(target.value)+Number(target.step||1));target.dispatchEvent(new Event('input',{bubbles:true}));}else target.click();}await nextFrame();rows.push({family,id,controlsResponded:E.encode(ui.demo.game)!==original,realStateUntouched:E.encode(state)===before});ui.dismiss();}report.interactionFamilies=rows;report.interactionsPassed=rows.every(r=>r.controlsResponded&&r.realStateUntouched);display();return rows;}
document.querySelector('#qa-interactions').onclick=interactions;
window.addEventListener('error',event=>{report.applicationError={message:event.message,file:event.filename,line:event.lineno,stack:event.error?.stack};display();});
if(new URLSearchParams(location.search).has('mobile')){await interactions();ui.open(17,{replay:true});ui.step=1;ui.show();await nextFrame();const shell=ui.root.querySelector('.tutorial-shell'),coach=ui.root.querySelector('.tutorial-coach'),demo=ui.root.querySelector('.tutorial-demo');const result={width:innerWidth,stacked:coach.getBoundingClientRect().top>=demo.getBoundingClientRect().bottom,documentFits:document.documentElement.scrollWidth<=innerWidth,shellFits:shell.getBoundingClientRect().width<=innerWidth,focusInside:ui.root.contains(document.activeElement),interactionsPassed:report.interactionsPassed};parent.postMessage({type:'tutorial-qa',result},location.origin);}
function frame(now){ui.tick(now);requestAnimationFrame(frame);}requestAnimationFrame(frame);display();
